text:
{
  "title": "استمارة التقديم على الوظائف ونموذج إقرار معالجة البيانات",
  "planted": [
    {
      "slot": "p1",
      "text": "تخضع كافة البيانات المقدمة من قبل المتقدم لتقدير الشركة المطلق، ولا يحق للمتقدم المطالبة بالاطلاع على السجلات الخاصة بملفه الوظيفي أو طلب تعديلها أو استرجاع المستندات المقدمة إلا وفقاً لما تقره الإدارة الداخلية وحدها."
    },
    {
      "slot": "p2",
      "text": "تحتفظ شركة ركائز التقنية بجميع مستندات وبیانات المتقدمين في أرشيفها الرقمي والورقي لفترات زمنية غير محدودة بغرض بناء قاعدة بيانات شاملة للكوادر المحتملة، دون التزام بإتلافها نهائياً."
    },
    {
      "slot": "p3",
      "text": "يقتصر طلب التقارير الطبية وشهادات اللياقة الصحية على المتقدمين للوظائف التشغيلية والميدانية حصراً التي تتطلب طبيعتها التأكد من سلامة البدن وفقاً لمتطلبات بيئة العمل الآمنة."
    }
  ],
  "neutral": [
    "تعني كلمة \"الشركة\" في هذا المستند شركة ركائز التقنية المسجلة في المملكة العربية السعودية، وتعني كلمة \"المتقدم\" الشخص الطبيعي الذي يملأ هذه الاستمارة بغرض التوظيف.",
    "تلتزم الشركة بتقديم بيئة عمل مهنية وفقاً للممارسات المتعارف عليها في قطاع الأعمال، مع احتفاظها بحق إنهاء إجراءات التوظيف في أي مرحلة دون أدنى مسؤولية قانونية.",
    "لا تتقاضى الشركة أي رسوم مالية نظير تقديم الطلب أو دراسة السيرة الذاتية للمتقدمين، وتعتبر كافة الطلبات المقدمة مجانية بالكامل.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية، وتختص الجهات القضائية بالفصل في أي نزاع قد ينشأ عنها.",
    "تعتبر جميع التصاميم والنماذج والشعارات الخاصة بشركة ركائز التقنية ملكية فكرية خالصة لها، ولا يحق لأي طرف ثالث استخدامها أو اقتباسها بأي شكل من الأشكال.",
    "تتمว كافة المراسلات الرسمية المتعلقة بالتوظيف عبر البريد الإلكتروني الرسمي المعتمد للشركة أو من خلال رقم الهواتف المعلنة، ولا تبت الشركة في الطلبات الواردة عبر قنوات غير رسمية."
  ]
}
